  gl_Position = vec4(ndc.x, -ndc.y, (1.0 - iMisc.z) * 2.0 - 1.0, 1.0);
  vUv = vec2(mix(iUv.x, iUv.z, c01.x), mix(iUv.y, iUv.w, c01.y));
